const p=cp.spawn(command,args,{stdio:['pipe','pipe','inherit']});
let next=1; const pending=new Map();
readline.createInterface({input:p.stdout}).on('line', line=>{const msg=JSON.parse(line);if(pending.has(msg.id)){pending.get(msg.id)(msg);pending.delete(msg.id);}});
const send=(x)=>p.stdin.write(JSON.stringify({jsonrpc:'2.0',...x})+'\n');
const call=async(method,params)=>{const id=next++;const msg=await new Promise(resolve=>{pending.set(id,resolve);send({id,method,params});});if(msg.error||msg.result?.isError)throw Error(JSON.stringify(msg.error??msg.result));return msg.result;};
const timeout=setTimeout(()=>{p.kill();process.exitCode=1;console.error('MCP round trip timed out');},35000);
